const alerts=()=>[...S.dl.filter(x=>!x.done&&x.date<=addD(TODAY,S.days)).sort((a,b)=>a.date.localeCompare(b.date)).map(x=>({k:x.id+(x.date<TODAY?'o':'s'),t:x.title,m:x.date<TODAY?t('Overdue since {0}',fmt(x.date)):t('Due {0}',fmt(x.date))})),...S.hb.filter(h=>h.remind&&h.freq!='weekly'&&sched(h,TODAY)&&!h.log[TODAY]&&nowHM()>=h.remind).map(h=>({k:h.id+TODAY,t:t('Habit: {0}',h.name),m:t('Scheduled today · reminder {0}',h.remind)}))];
function bell(){const a=alerts(),n=a.filter(y=>!S.seen.includes(y.k)).length;$('#bc').textContent=n||'';$('#bc').style.display=n?'':'none'}
$('#bb').onclick=()=>{const p=$('#np');if(!p.hidden){p.hidden=true;return}const a=alerts();p.innerHTML=`<div style="display:flex;gap:8px;align-items:center;margin-bottom:6px"><b style="flex:1">${t('Reminders')}</b><select id="pd" style="width:auto" aria-label="${t('Remind me before')}"><option value="1">${t('1 day')}</option><option value="3">${t('3 days')}</option><option value="7">${t('7 days')}</option></select><button class="btn s sm" id="mr">${t('Mark read')}</button></div>`+(a.map(({k,t,m})=>`<div class="row"><div><b>${esc(t)}</b>${S.seen.includes(k)?'':' 🔵'}<div class="mu">${esc(m)}</div></div></div>`).join('')||'<p class="mu">'+t('You’re all caught up.')+'</p>')+'<p class="mu">'+t('In-app reminders only. Email or push reminders need a server.')+'</p>';$('#pd').value=S.days;$('#pd').onchange=()=>{S.days=+$('#pd').value;save();bell();$('#bb').click();$('#bb').click()};$('#mr').onclick=()=>{S.seen=[...new Set([...S.seen,...a.map(y=>y.k)])];save();bell();$('#np').hidden=true};p.hidden=false};
document.addEventListener('click',e=>{if(!e.target.closest('.sr'))$('#drop').hidden=true;if(!e.target.closest('.bell'))$('#np').hidden=true});
new MutationObserver(()=>document.querySelectorAll('table').forEach(t=>{const h=[...t.querySelectorAll('thead th')].map(x=>x.textContent);t.querySelectorAll('tbody tr').forEach(r=>[...r.children].forEach((c,i)=>{if(h[i]&&!c.dataset.l&&c.colSpan<2)c.dataset.l=h[i]}))})).observe($('#m'),{childList:true,subtree:true});$('#ttl').onclick=()=>show('home');$('#mm').onclick=()=>$('#nl').classList.toggle('open');navWire();
/* ---- theme + language switchers (preferences saved separately from app data) ---- */
function applyTheme(){const d=THEME=='dark',b=$('#thm'),l=t(d?'Switch to light mode':'Switch to dark mode');document.documentElement.dataset.theme=THEME;b.setAttribute('aria-pressed',d);b.setAttribute('aria-label',l);b.title=l;const m=document.querySelector('meta[name=theme-color]');if(m)m.content=d?'#171b2e':'#ffffff'}
function applyLang(){const h=document.documentElement;h.lang=LANG;h.dir=LANG=='ar'?'rtl':'ltr';document.querySelectorAll('[data-i]').forEach(e=>e.textContent=t(e.dataset.i));document.querySelectorAll('[data-ip]').forEach(e=>e.placeholder=t(e.dataset.ip));document.querySelectorAll('[data-ia]').forEach(e=>{const v=t(e.dataset.ia);e.setAttribute('aria-label',v);e.title=v});const g=$('#lgt'),lb=t(LANG=='ar'?'Switch to English':'Switch to Arabic');g.textContent=LANG=='ar'?'English':'العربية';g.lang=LANG=='ar'?'en':'ar';$('#lg').setAttribute('aria-label',lb);$('#lg').title=lb;const md=document.querySelector('meta[name=description]');if(md)md.content=t('Unihub for National University Students — a convenient platform for organizing academic activities and managing student life.');applyTheme()}
$('#thm').onclick=()=>{THEME=THEME=='dark'?'light':'dark';try{localStorage.setItem(TK,THEME)}catch(e){}applyTheme()};
$('#lg').onclick=()=>{LANG=LANG=='ar'?'en':'ar';try{localStorage.setItem(LK,LANG)}catch(e){}applyLang();$('#np').hidden=true;$('#drop').hidden=true;({home,deadlines,academics,books,goals,habits,budget,about})[P]();bell()};
applyLang();
const _s=show;show=function(p){_s(p);bell()};
show(['home','deadlines','academics','books','goals','habits','budget','about'].includes(location.hash.slice(1))?location.hash.slice(1):'home');
